def _channel(sweep, lab):
    x = np.asarray(sweep['cmd_stress'], dtype=float)
    y = np.asarray(sweep['true_stress'], dtype=float)
    use = (np.asarray(sweep['lab_id']) == lab) & np.isfinite(x) & np.isfinite(y)
    return (x[use], y[use])

def _fit(past, hold, x, dt, times, curves, rates, rate_weight=1.0):
    from scipy.optimize import least_squares
    curve_mask, rate_mask = (np.isfinite(curves), np.isfinite(rates))
    target = np.r_[curves[curve_mask], rate_weight * rates[rate_mask]]

    def profile(log_taus):
        curve, rate = _design(past, hold, x, dt, times, np.exp(log_taus))
        matrix = np.vstack((curve[curve_mask], rate_weight * rate[rate_mask]))
        weights = np.linalg.lstsq(matrix, target, rcond=1e-10)[0]
        return (np.einsum('ij,j->i', matrix, weights) - target, weights)
    best = min((least_squares(lambda q: profile(q)[0], np.log(start), bounds=np.log([0.02, 40.0]), max_nfev=120) for start in ((0.1, 1.0), (0.3, 2.0), (0.65, 4.0), (1.3, 8.0))), key=lambda result: result.cost)
    log_taus = np.sort(best.x)
    err, weights = profile(log_taus)
    nc = curve_mask.sum()

    def mad(v):
        return max(1e-06, 1.4826 * np.median(np.abs(v - np.median(v))))

    def raw(p):
        curve, rate = _design(past, hold, x, dt, times, np.exp(p[:2]))
        return np.r_[(curve @ p[2:])[curve_mask] - curves[curve_mask], (rate @ p[2:])[rate_mask] - rates[rate_mask]]
    p = np.r_[log_taus, weights]
    for _ in range(2):
        e = raw(p)
        scale = np.r_[np.full(nc, mad(e[:nc])), np.full(rate_mask.sum(), mad(e[nc:]))]
        p = least_squares(lambda q: raw(q) / scale, p, loss='cauchy', f_scale=2.5, bounds=(np.r_[np.log([0.02, 0.02]), np.full(7, -np.inf)], np.r_[np.log([40.0, 40.0]), np.full(7, np.inf)]), x_scale='jac', max_nfev=120).x
    if p[0] > p[1]:
        p[:2] = p[:2][::-1]
        p[2:4] = p[2:4][::-1]
    return (np.exp(p[:2]), p[2:])

def _physical(split, calibration):
    g, b = calibration[split['lab_id']].T
    return (g[:, None] * split['past_stress_cmd'] + b[:, None], g * split['stress_hold_cmd'] + b)

def _basis(past, hold, dt, times, taus):
    later = np.r_[np.cumsum(dt[:0:-1])[::-1], 0.0]
    memory_weights = -np.expm1(-dt[:, None] / taus) * np.exp(-later[:, None] / taus)
    gap = hold[:, None] - past @ memory_weights
    response = -np.expm1(-times[:, None] / taus)
    return (gap[:, None, :] * response, gap / taus)
